<script>
const riddleTable = document.getElementById("riddleTable");
const missingCell = riddleTable.rows[2].cells[2];
// Define function to split number into pairs
function splitNumber(number) {
  const firstHalf = Math.floor(number / 10);
  const secondHalf = number % 10;
  return [firstHalf, secondHalf];
}
// Find missing pair
const pairs = [];
for (let i = 0; i < riddleTable.rows.length; i++) {
  const cell = riddleTable.rows[i].cells;
  if (i !== 2) {
    const number = parseInt(cell[0].textContent);
    const pair = splitNumber(number);
    pairs.push(pair);
  }
}
// Find missing number based on missing pair
const missingPair = pairs[2];
const sumOfMissingPair = missingPair[0] + missingPair[1];
const missingNumber = sumOfMissingPair * 10 + sumOfMissingPair + 1;
// Display missing number
missingCell.textContent = missingNumber;
</script>
</body>
```
